"""Small, reviewed starter bank for the rule-based LDICA mastery engine."""
QUESTIONS = [
 {"key":"opamp-inverting-gain","unit":1,"concept":"inverting-amplifier","title":"Inverting amplifier gain","q":"For an ideal inverting amplifier, Rin = 10 kΩ and Rf = 100 kΩ. What is Av?","choices":["+10","−10","+11","−0.1"],"answer":1,"explanation":"Av = −Rf/Rin = −100/10 = −10. The negative sign indicates phase inversion.","misconception":"The sign of gain may have been ignored, or the resistor ratio may have been reversed."},
 {"key":"opamp-noninverting-gain","unit":1,"concept":"non-inverting-amplifier","title":"Non-inverting gain","q":"For a non-inverting amplifier with Rf = 30 kΩ and Rg = 10 kΩ, the ideal closed-loop gain is:","choices":["3","4","−3","0.25"],"answer":1,"explanation":"Av = 1 + Rf/Rg = 1 + 30/10 = 4.","misconception":"The non-inverting gain includes the extra 1; it is not simply Rf/Rg."},
 {"key":"opamp-virtual-ground","unit":1,"concept":"inverting-amplifier","title":"Virtual ground","q":"In a correctly operating ideal inverting amplifier with negative feedback and V+ grounded, V− is approximately:","choices":["At the positive supply rail","At ground potential without being physically wired to ground","Always equal to the output","An open circuit at any voltage"],"answer":1,"explanation":"Negative feedback drives the differential input voltage close to zero. The inverting node is a virtual ground, not a direct ground connection.","misconception":"A virtual ground is a feedback result; it is not necessarily a physical wire to ground."},
 {"key":"timer-trigger-level","unit":2,"concept":"ic-555-timer","title":"555 trigger threshold","q":"For the classic 555 timer's internal divider, the nominal trigger comparator reference is approximately:","choices":["VCC/3","VCC/2","2VCC/3","VCC"],"answer":0,"explanation":"The trigger comparator threshold is nominally VCC/3; the threshold comparator reference is nominally 2VCC/3.","misconception":"The trigger and threshold reference levels may have been swapped."},
 {"key":"timer-astable-frequency","unit":2,"concept":"ic-555-timer","title":"555 astable timing","q":"In the usual 555 astable approximation, increasing both timing resistors while keeping C fixed will generally:","choices":["Increase frequency","Decrease frequency","Leave frequency unchanged","Make the capacitor disappear from the equation"],"answer":1,"explanation":"The timing period is proportional to the resistance-capacitance terms, so increasing resistance generally increases period and lowers frequency.","misconception":"Frequency is inverse to period; a longer charge/discharge time means a lower frequency."},
 {"key":"pll-lock","unit":2,"concept":"phase-locked-loop","title":"PLL lock","q":"A phase-locked loop is considered locked when:","choices":["Its output is always zero","The feedback and reference frequencies have settled to the required relationship with a bounded phase difference","The loop filter is disconnected","The reference signal has no frequency"],"answer":1,"explanation":"In lock, the feedback frequency tracks the reference relationship and the phase error settles to a bounded value for the loop's operating conditions.","misconception":"Lock is about tracking and phase relationship, not zero output or a disconnected loop."},
 {"key":"adc-codes","unit":3,"concept":"data-converters","title":"ADC code count","q":"An ideal 8-bit ADC can represent how many distinct digital codes?","choices":["8","16","128","256"],"answer":3,"explanation":"An N-bit converter has 2^N possible codes. For 8 bits, 2^8 = 256.","misconception":"Bit count is the exponent; it is not the number of output codes itself."},
 {"key":"adc-lsb","unit":3,"concept":"data-converters","title":"ADC resolution","q":"Ignoring endpoint convention differences, the nominal code-step scale of an N-bit converter over reference span Vref is closest to:","choices":["Vref × 2^N","Vref / 2^N","N / Vref","Vref + N"],"answer":1,"explanation":"A common ideal quantisation step approximation is Vref/2^N. Some specifications use Vref/(2^N−1) for endpoint mapping, so follow the convention stated in the problem.","misconception":"Resolution is a voltage interval per code and decreases as the number of bits increases."},
 {"key":"dac-binary-weight","unit":3,"concept":"data-converters","title":"Binary-weighted DAC","q":"In an ideal binary-weighted DAC, the most significant bit contributes a weight that is:","choices":["Smaller than the least significant bit","Equal to every other bit","Greater than the least significant bit","Always zero"],"answer":2,"explanation":"Binary place values are weighted by powers of two; the MSB has a greater weight than the LSB for the same word width.","misconception":"Binary place value grows from the least significant bit toward the most significant bit."},
 {"key":"logic-mux","unit":4,"concept":"multiplexers","title":"Multiplexer function","q":"A multiplexer primarily:","choices":["Stores a bit permanently","Selects one of several data inputs for an output","Converts analogue voltage into binary code","Counts clock pulses"],"answer":1,"explanation":"Select lines determine which data input is routed to the output.","misconception":"A multiplexer selects data; storage and counting are different functions."},
 {"key":"logic-xor","unit":4,"concept":"logic-gates","title":"XOR behavior","q":"For a two-input XOR gate, the output is 1 when:","choices":["Both inputs are 0 only","Both inputs are 1 only","The two inputs are different","The two inputs are the same"],"answer":2,"explanation":"XOR is high when the inputs differ: 01 and 10 produce 1.","misconception":"XOR means exclusive OR, not ordinary OR or equality."},
 {"key":"logic-adder-carry","unit":4,"concept":"adders","title":"Full-adder carry","q":"A full adder has inputs A, B, Cin. Its carry output is 1 when:","choices":["No inputs are 1","At least two of the three inputs are 1","Only A is 1","The sum output is always 1"],"answer":1,"explanation":"Cout = AB + ACin + BCin, so a carry is generated when at least two input bits are high.","misconception":"Carry represents the majority condition of the three input bits."},
 {"key":"sequential-dff","unit":5,"concept":"d-flip-flop","title":"D flip-flop","q":"For a conventional edge-triggered D flip-flop, at the active clock edge:","choices":["Q becomes D","Q always toggles","Q becomes not-D regardless of configuration","Q resets on every edge"],"answer":0,"explanation":"The D input is sampled at the active clock edge and transferred to Q; Q holds its state between active edges, absent overriding controls.","misconception":"A D flip-flop samples data; toggling is associated with T flip-flop behavior."},
 {"key":"sequential-jk","unit":5,"concept":"jk-flip-flop","title":"JK toggle condition","q":"For a conventional edge-triggered JK flip-flop, J = 1 and K = 1 causes:","choices":["Hold state","Set state only once and never change","Toggle state at the active clock edge","An invalid input condition in every JK implementation"],"answer":2,"explanation":"For the conventional JK characteristic, J=K=1 toggles the stored output on the active clock edge.","misconception":"The JK design defines the condition that is invalid for the basic SR latch as a toggle condition."},
 {"key":"memory-dram-refresh","unit":5,"concept":"dynamic-ram","title":"DRAM refresh","q":"Why does conventional DRAM require refresh?","choices":["It stores data only in magnetic domains","Cell charge leaks over time","It has no address inputs","Its data is permanently fixed at manufacture"],"answer":1,"explanation":"DRAM cells store information using charge that leaks, so the stored state must be refreshed periodically while powered.","misconception":"DRAM's charge-based storage is volatile and needs periodic refresh."},
]

BY_KEY = {question["key"]: question for question in QUESTIONS}
